# Effects on audio buses (BlitzLLVM), rendered through SDL's disk audio driver.
# Usage: audio_effects.py <blitzcc> <work directory>. Skipped (77) when the disk driver is not available.
import math
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from audio_common import *  # noqa: E402,F403

tone("tone.wav", 22050, 1, 16)
reference = steady_peak(play("tone.wav")[0])

# Effects on buses (BlitzLLVM). The tone is 441 Hz. A filter set to it lets through what its curve says (-3 dB for the low- and high-pass),
# a parameter step does not click, the limiter stays below its ceiling, and the repeats of an echo and the tail of a reverb ring out after
# the sound has ended.
FX = 'Include "<audio.bb>"\nb = CreateAudioBus()\nSoundBus s, b\ne = AddAudioEffect(b, BB_EFFECT_%s)\n'


def fx_setup(effect, *params):
	return FX % effect + "".join("AudioEffectParam e, BB_EFFECTPARAM_%s, %s\n" % (name, value) for name, value in params)


level = reference / 32767.0
for what, setup, ratio, tolerance in (
	("low-pass at the tone", fx_setup("LOWPASS", ("FREQUENCY", 441)), 0.7071, 0.03),
	("low-pass far above the tone", fx_setup("LOWPASS", ("FREQUENCY", 10000)), 1.0, 0.03),
	("low-pass two octaves below", fx_setup("LOWPASS", ("FREQUENCY", 110.25)), 1.0 / math.sqrt(1 + 4**4), 0.1),
	("high-pass at the tone", fx_setup("HIGHPASS", ("FREQUENCY", 441)), 0.7071, 0.03),
	("band-pass at the tone", fx_setup("BANDPASS", ("FREQUENCY", 441)), 1.0, 0.03),
	("peak EQ of +6 dB at the tone", fx_setup("PEAK", ("FREQUENCY", 441), ("GAIN", 6.0206)), 2.0, 0.03),
	("low shelf of -12 dB above the tone", fx_setup("LOWSHELF", ("FREQUENCY", 10000), ("GAIN", -12.041)), 0.25, 0.04),
	("high shelf of +6 dB below the tone", fx_setup("HIGHSHELF", ("FREQUENCY", 40), ("GAIN", 6.0206)), 2.0, 0.03),
	("a low-pass with half the mix", fx_setup("LOWPASS", ("FREQUENCY", 441), ("MIX", 0.5)), math.sqrt(0.25 + 0.125), 0.03),
	("a bypassed low-pass", fx_setup("LOWPASS", ("FREQUENCY", 50)) + "AudioEffectBypass e, True\n", 1.0, 0.03),
	("a low-pass on the master bus", 'Include "<audio.bb>"\ne = AddAudioEffect(0, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 441\n', 0.7071, 0.03),
	("a compressor", fx_setup("COMPRESSOR", ("THRESHOLD", -24), ("RATIO", 100), ("ATTACK", 0)), 10 ** ((-24 + (20 * math.log10(level) + 24) / 100) / 20) / level, 0.06),
	("a low-pass from an audio scene", fx_setup("LOWPASS") + "scene = CreateAudioScene()\nAudioSceneParam scene, e, BB_EFFECTPARAM_FREQUENCY, 441\nApplyAudioScene scene\n", 0.7071, 0.03),
	("a blend of two scenes at 1", fx_setup("LOWPASS") + "a = CreateAudioScene()\nz = CreateAudioScene()\nAudioSceneParam z, e, BB_EFFECTPARAM_FREQUENCY, 441\nBlendAudioScene a, z, 1\n", 0.7071, 0.03),
):
	peak = steady_peak(play("tone.wav", setup)[0])
	check("effect, %s: peak %d is %.3f of %d" % (what, peak, ratio, reference), abs(peak - reference * ratio) <= reference * ratio * tolerance + 2)
peak = steady_peak(play("tone.wav", fx_setup("DISTORTION", ("DRIVE", 1)))[0])
check("effect, distortion drives the tone to full scale: peak %d" % peak, peak > 30000)
samples = play("tone.wav", fx_setup("LOFI", ("BITS", 3)))[0]
values = set(samples[len(samples) // 4 : len(samples) // 2])
check("effect, lo-fi with 3 bits: %d different values" % len(values), 2 <= len(values) <= 5)
ceiling = 32767 * 10 ** (-12 / 20.0)
samples = play("tone.wav", 'Include "<audio.bb>"\nb = CreateAudioBus()\na = CreateAudioBus(b)\nAudioBusVolume a, 4\nSoundBus s, a\ne = AddAudioEffect(b, BB_EFFECT_LIMITER)\nAudioEffectParam e, BB_EFFECTPARAM_CEILING, -12\n')[0]
peak = max(abs(v) for v in samples)
check("effect, limiter: peak %d stays at its ceiling of %d" % (peak, ceiling), ceiling * 0.9 < peak <= ceiling + 2)
# A step of a parameter without a fade glides: no sample moves further from the one before than the tone itself does at its loudest.
for what, setup, after, loudest in (
	("a low-pass closing", fx_setup("LOWPASS"), "Delay 300\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 100", 1.0),
	("a peak EQ going up 12 dB", fx_setup("PEAK", ("FREQUENCY", 441)), "Delay 300\nAudioEffectParam e, BB_EFFECTPARAM_GAIN, 12", 10 ** (12 / 20.0)),
	("a low-pass bypassed", fx_setup("LOWPASS", ("FREQUENCY", 100)), "Delay 300\nAudioEffectBypass e, True", 1.0),
):
	samples = play("tone.wav", setup, after)[0]
	natural = 2 * math.pi * 441 / OUTPUT_RATE * reference * loudest
	loud = [i for i, v in enumerate(samples) if abs(v) > 30]
	start = loud[0] + 4000 if loud else 0  # Past the start of the sound, which comes in mid-block.
	step = max([abs(samples[i + 1] - samples[i]) for i in range(start, len(samples) - 1)] + [0])
	check("effect, %s: largest step %d is within the tone's %d" % (what, step, natural), step <= natural * 1.1 + 2)
# A short sound (10 cycles, 23 ms) and what comes after it.
tone("blip.wav", 22050, 1, 16, cycles=10)


def bursts(samples, window=441):
	"""The loudest sample of every 10 ms, from the start of the sound."""
	loud = [i for i, v in enumerate(samples) if abs(v) > 30]
	if not loud:
		return []
	return [max(abs(v) for v in samples[i : i + window]) for i in range(loud[0], len(samples) - window, window)]


levels = bursts(play("blip.wav", fx_setup("ECHO", ("DELAY", 0.25), ("FEEDBACK", 0.5), ("DAMPING", 0)), loop=False, milliseconds=1500)[0])
first = max(levels[0:3]) if levels else 0
repeats = [max(levels[25 * n - 1 : 25 * n + 3]) if len(levels) > 25 * n + 3 else 0 for n in (1, 2, 3)]
between = max(levels[5:23]) if len(levels) > 23 else 0
check("effect, echo: repeats at 0.25, 0.5 and 0.75 s are %s of %d" % (repeats, first), first > 1000 and abs(repeats[0] / first - 1.0) < 0.05 and abs(repeats[1] / first - 0.5) < 0.05 and abs(repeats[2] / first - 0.25) < 0.05)
check("effect, echo: silent between the repeats (%d)" % between, between < first * 0.01 + 2)
levels = bursts(play("blip.wav", fx_setup("REVERB", ("MIX", 0.5)), loop=False, milliseconds=3500)[0])
early = max(levels[10:40]) if len(levels) > 40 else 0
late = max(levels[250:300]) if len(levels) > 300 else 0
check("effect, reverb: the tail rings out after the sound (%d at 0.1 to 0.4 s) and dies down (%d at 2.5 to 3 s)" % (early, late), early > 30 and late < early * 0.05)
samples = play("blip.wav", 'Include "<audio.bb>"\nb = CreateAudioBus()\nSoundBus s, b\n', loop=False)[0]
check("effect, a bus without effects is silent after the sound", max(bursts(samples)[5:] + [0]) <= 2)

# Effects on channels, and sends. The tone plays on the master bus; what the channel sends adds to it, panned like the channel.
CH = 'Include "<audio.bb>"\nb = CreateAudioBus()\n'
for what, after, ratio in (
	("a low-pass on the channel", "e = AddChannelEffect(c, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 441", 0.7071),
	("two filters on the channel", "e = AddChannelEffect(c, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 441\nf = AddChannelEffect(c, BB_EFFECT_PEAK, 0)\nAudioEffectParam f, BB_EFFECTPARAM_FREQUENCY, 441\nAudioEffectParam f, BB_EFFECTPARAM_GAIN, 6.0206", 1.4142),
	("a freed channel effect", "e = AddChannelEffect(c, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 50\nFreeAudioEffect e", 1.0),
	("a send to an empty bus", "ChannelSend c, b, 1", 2.0),
	("a send at half the level", "ChannelSend c, b, 0.5", 1.5),
	("a send removed again", "ChannelSend c, b, 1\nChannelSend c, b, 0", 1.0),
	("a send to a bus that is turned off", "AudioBusVolume b, 0\nChannelSend c, b, 1", 1.0),
	("a send panned to the left", "ChannelPan c, -1\nChannelSend c, b, 1", 2.0),
	("a send panned to the right", "ChannelPan c, 1\nChannelSend c, b, 1", 0.0),
	("a send to a bus with a low-pass", "e = AddAudioEffect(b, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 441\nChannelSend c, b, 1", abs(1 - 0.70711j)),
	("a send to a freed bus goes to its parent", "a = CreateAudioBus(b)\nAudioBusVolume b, 0.5\nChannelSend c, a, 1\nFreeAudioBus a", 1.5),
	("a channel effect before its send", "e = AddChannelEffect(c, BB_EFFECT_LOWPASS)\nAudioEffectParam e, BB_EFFECTPARAM_FREQUENCY, 441\nChannelSend c, b, 1", 1.4142),
):
	peak = steady_peak(play("tone.wav", CH, after)[0])
	check("channel, %s: peak %d is %.3f of %d" % (what, peak, ratio, reference), abs(peak - reference * ratio) <= reference * ratio * 0.03 + 3)
error = play("tone.wav", CH, "For i = 1 To 5\n\tChannelSend c, CreateAudioBus(), 1\nNext", milliseconds=100)[1]
check("channel, a fifth send stops the program", "can send to 4 buses at most" in error)
samples = play("tone.wav", CH, "ChannelSend c, b, 1\nDelay 300\nChannelSend c, b, 0.01")[0]
natural = 2 * math.pi * 441 / OUTPUT_RATE * reference * 2
loud = [i for i, v in enumerate(samples) if abs(v) > 30]
start = loud[0] + 4000 if loud else 0
step = max([abs(samples[i + 1] - samples[i]) for i in range(start, len(samples) - 1)] + [0])
check("channel, a send level that jumps glides: largest step %d is within the tone's %d" % (step, natural), step <= natural * 1.1 + 2)
samples = play("blip.wav", CH, "e = AddChannelEffect(c, BB_EFFECT_ECHO)\nAudioEffectParam e, BB_EFFECTPARAM_DELAY, 0.25", loop=False)[0]
check("channel, an echo on a channel ends with its sound", max(bursts(samples)[5:] + [0]) <= 2)
levels = bursts(play("blip.wav", CH + "e = AddAudioEffect(b, BB_EFFECT_ECHO)\nAudioEffectParam e, BB_EFFECTPARAM_DELAY, 0.25\nAudioEffectParam e, BB_EFFECTPARAM_MIX, 1\n", "ChannelSend c, b, 1", loop=False)[0])
first = max(levels[0:3]) if levels else 0
repeat = max(levels[24:28]) if len(levels) > 28 else 0
check("channel, a send to a bus with an echo repeats at 0.25 s: %d of %d" % (repeat, first), first > 1000 and abs(repeat / first - 1.0) < 0.05)

# Air absorption: a source 1000 meters away, without falloff or doppler, so that only the low-pass changes it. An amount of 10 puts the
# cutoff at 2,000,000 / (10 * 1000) = 200 Hz, which leaves 1 / sqrt(1 + (441 / 200)^4) of the 441 Hz tone.
def play_far(setup="", after=""):
	with open("play.bb", "w") as source:
		source.write(
			's = Load3DSound("tone.wav")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, 1000\n'
			"CreateListener listener, 0, 0, 1\n%s\nc = EmitSound(s, source)\n%s\nDelay 1500\n" % (setup, after)
		)
	return steady_peak(render()[0])


near = play_far()
for what, setup, after, ratio in (
	("air absorption at 1 km", "ListenerAirAbsorption 10", "", 1 / math.sqrt(1 + (441 / 200.0) ** 4)),
	("air absorption set while it plays", "", "ListenerAirAbsorption 10", 1 / math.sqrt(1 + (441 / 200.0) ** 4)),
	("air absorption turned off again", "ListenerAirAbsorption 10", "ListenerAirAbsorption 0", 1.0),
	("air absorption that is small", "ListenerAirAbsorption 0.1", "", 1 / math.sqrt(1 + (441 / 20000.0) ** 4)),
):
	peak = play_far(setup, after)
	check("air, %s: peak %d is %.3f of %d" % (what, peak, ratio, near), abs(peak - near * ratio) <= near * ratio * 0.03 + 3)

sys.exit(1 if failures else 0)
